import { useEffect, useState } from "react";
import { Link, NavLink, useLocation } from "react-router-dom";
import { Phone, Menu, X, ArrowUpRight } from "lucide-react";

const LOGO = "https://customer-assets.emergentagent.com/job_roofing-pro-32/artifacts/dci1r31y_20dc139a-c170-45f5-b0ae-a778b1df8fb0.png";

const links = [
  { to: "/", label: "Home" },
  { to: "/services", label: "Services" },
  { to: "/about", label: "About" },
  { to: "/reviews", label: "Reviews" },
  { to: "/contact", label: "Contact" },
];

export default function Navbar() {
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const { pathname } = useLocation();
  const isHome = pathname === "/";

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => setOpen(false), [pathname]);

  // On home page, navbar overlays the dark hero (transparent), elsewhere always solid
  const isDarkOver = isHome && !scrolled;

  return (
    <header
      className={`fixed top-0 inset-x-0 z-50 transition-all duration-300 ${
        scrolled
          ? "backdrop-blur-2xl bg-white/30 border-b border-white/40 shadow-[0_8px_24px_-12px_rgba(11,18,32,0.08)]"
          : isHome
          ? "bg-transparent"
          : "backdrop-blur-2xl bg-white/30 border-b border-white/40"
      }`}
      data-testid="site-navbar"
    >
      <div className="sf-container flex items-center justify-between h-24">
        <Link to="/" className="flex items-center group" data-testid="logo-link">
          <img
            src={LOGO}
            alt="SkyForge Roofing"
            className={`h-20 md:h-24 w-auto object-contain transition-all duration-300 group-hover:scale-[1.03] ${
              isDarkOver ? "" : "brightness-0"
            }`}
          />
        </Link>

        <nav className="hidden lg:flex items-center gap-1 p-1 rounded-full border border-transparent">
          <div className={`flex items-center rounded-full px-1 py-1 ${isDarkOver ? "bg-white/8 border border-white/12 backdrop-blur-xl" : "bg-slate-100/80 border border-slate-200"}`}>
            {links.map((l) => (
              <NavLink
                key={l.to}
                to={l.to}
                end={l.to === "/"}
                className={({ isActive }) =>
                  `px-4 py-2 text-sm font-medium rounded-full transition-all duration-200 ${
                    isActive
                      ? isDarkOver
                        ? "bg-white text-slate-900"
                        : "bg-white text-slate-900 shadow-sm"
                      : isDarkOver
                      ? "text-slate-200 hover:text-white"
                      : "text-slate-600 hover:text-slate-900"
                  }`
                }
                data-testid={`nav-link-${l.label.toLowerCase()}`}
              >
                {l.label}
              </NavLink>
            ))}
          </div>
        </nav>

        <div className="hidden lg:flex items-center gap-3">
          <a
            href="tel:+16477455082"
            className={`flex items-center gap-2 text-sm font-semibold ${isDarkOver ? "text-white/90 hover:text-white" : "text-slate-700 hover:text-slate-900"}`}
            data-testid="nav-call-link"
          >
            <Phone className="w-4 h-4" /> 647-745-5082
          </a>
          <Link
            to="/contact"
            className="sf-btn sf-btn-primary"
            data-testid="nav-quote-button"
          >
            Free Quote <ArrowUpRight className="w-4 h-4" />
          </Link>
        </div>

        <button
          className={`lg:hidden p-2 rounded-lg ${isDarkOver ? "text-white" : "text-slate-900"}`}
          onClick={() => setOpen(!open)}
          aria-label="Toggle menu"
          data-testid="mobile-menu-toggle"
        >
          {open ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
        </button>
      </div>

      {open && (
        <div className="lg:hidden border-t border-slate-200 bg-white" data-testid="mobile-menu">
          <div className="sf-container py-5 flex flex-col gap-1">
            {links.map((l) => (
              <NavLink
                key={l.to}
                to={l.to}
                end={l.to === "/"}
                className={({ isActive }) =>
                  `px-3 py-3 text-sm font-semibold rounded-lg ${
                    isActive ? "bg-blue-50 text-blue-600" : "text-slate-700 hover:bg-slate-50"
                  }`
                }
                data-testid={`mobile-nav-link-${l.label.toLowerCase()}`}
              >
                {l.label}
              </NavLink>
            ))}
            <a href="tel:+16477455082" className="mt-3 sf-btn sf-btn-primary w-full" data-testid="mobile-call-button">
              <Phone className="w-4 h-4" /> 647-745-5082
            </a>
          </div>
        </div>
      )}
    </header>
  );
}
